const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const taiwan = ee.Geometry.Rectangle([120.0, 22.0, 122.0, 25.5]);

  const period1Start = '2020-02-10';
  const period1End = '2020-02-26';
  const period2Start = '2020-04-20';
  const period2End = '2020-05-13';

  // 2. Data Acquisition
  const s5p = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density');

  const col1 = s5p.filterDate(period1Start, period1End)
    .filterBounds(taiwan);

  const col2 = s5p.filterDate(period2Start, period2End)
    .filterBounds(taiwan);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Period 1 (Feb 10-25) Images: ${size1}`);
  console.log(`Period 2 (Apr 20-May 12) Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("Missing data for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Apply quality mask and calculate means
  function maskQuality(image) {
    const qa = image.select('qa_value');
    const mask = qa.gte(0.5);
    return image.updateMask(mask);
  }

  const s5pQA = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2');

  const col1QA = s5pQA.filterDate(period1Start, period1End)
    .filterBounds(taiwan)
    .map(maskQuality)
    .select('tropospheric_NO2_column_number_density');

  const col2QA = s5pQA.filterDate(period2Start, period2End)
    .filterBounds(taiwan)
    .map(maskQuality)
    .select('tropospheric_NO2_column_number_density');

  const mean1 = col1QA.mean();
  const mean2 = col2QA.mean();

  // 4. Calculate statistics
  const stats1 = mean1.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: taiwan,
    scale: 5000,
    maxPixels: 1e9
  });

  const stats2 = mean2.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: taiwan,
    scale: 5000,
    maxPixels: 1e9
  });

  const val1 = stats1.get('tropospheric_NO2_column_number_density_mean').getInfo();
  const count1 = stats1.get('tropospheric_NO2_column_number_density_count').getInfo();
  const val2 = stats2.get('tropospheric_NO2_column_number_density_mean').getInfo();
  const count2 = stats2.get('tropospheric_NO2_column_number_density_count').getInfo();

  console.log(`Period 1 Mean NO2: ${val1}, Valid Pixels: ${count1}`);
  console.log(`Period 2 Mean NO2: ${val2}, Valid Pixels: ${count2}`);

  // 5. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after quality masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (val1 === null || val2 === null || isNaN(val1) || isNaN(val2)) {
    console.log("Calculation returned invalid values.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (val1 < 0 || val2 < 0 || val1 > 1 || val2 > 1) {
    console.log("NO2 values out of expected range.");
    console.log("<answer>C3</answer>");
    return;
  }

  const increase = val2 > val1;
  const percentChange = ((val2 - val1) / val1 * 100).toFixed(2);
  console.log(`Change: ${percentChange}%`);

  if (increase) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
